扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: #!/usr/bin/env node
L2: /**
L3:  * RENDER evidence: full-page screenshots at 390, 768 and 1440 px, plus the
L4:  * content-overflow audit, in one command.
L5:  *
L6:  * Why it exists: about one user message in five was a screenshot saying a
L7:  * "fixed" visual bug was not fixed, because the fix had been verified by reading
L8:  * code. Before claiming a visual fix or a finished screen, run this and quote
L9:  * what it prints.
L10:  *
L11:  *   node ~/.claude/skills/design-pipeline/scripts/shot.mjs <url | file.html> [--widths=390,768,1440] [--out=dir]
L12:  *
L13:  * Screenshots land in `.design/shots/` of the project (git toplevel of cwd, else
L14:  * cwd) as `<name>-<width>.png`; keep `.design/` in .gitignore. The audit is
L15:  * verify_overflow.mjs's own function, read from that file so there is one source
L16:  * of truth, and it also reports the page's scrollWidth against the viewport.
L17:  *
L18:  * Needs Playwright with Chromium (Lightpanda has no rendering engine). When it
L19:  * cannot render it exits 1: a missing browser must never read as a pass.
L20:  * Exit 1 as well on horizontal overflow, clipped text or overlapping controls.
L21:  */
L22: import { readFileSync, mkdirSync, existsSync } from 'node:fs';
L23: import { execFileSync } from 'node:child_process';
L24: import { createRequire } from 'node:module';
L25: import { dirname, join, resolve, basename } from 'node:path';
L26: import { fileURLToPath, pathToFileURL } from 'node:url';
L27: 
L28: const HERE = dirname(fileURLToPath(import.meta.url));
L29: const argv = process.argv.slice(2);
L30: const target = argv.find(a => !a.startsWith('--'));
L31: const opt = (name, dflt) => (argv.find(a => a.startsWith(`--${name}=`)) || '').split('=').slice(1).join('=') || dflt;
L32: 
L33: if (!target) {
L34:   console.log('usage: node ~/.claude/skills/design-pipeline/scripts/shot.mjs <url | file.html> [--widths=390,768,1440] [--out=dir]');
L35:   process.exit(1);
L36: }
L37: const widths = opt('widths', '390,768,1440').split(',').map(Number).filter(Boolean);
L38: 
L39: const fail = (msg) => { console.log(`shot: FAIL - ${msg}`); process.exit(1); };
L40: 
L41: // --- Playwright: next to this script, else in the project, else not at all ----
L42: const spec = process.env.SHOT_PLAYWRIGHT || 'playwright';
L43: let chromium;
L44: try { ({ chromium } = await import(spec)); }
L45: catch {
L46:   try {
L47:     const req = createRequire(join(process.cwd(), 'noop.js'));
L48:     ({ chromium } = await import(pathToFileURL(req.resolve(spec)).href));
L49:   } catch {
L50:     fail(`playwright not installed (${spec}) - cannot render, so this is NOT a pass. npm i -D playwright && npx playwright install chromium`);
L51:   }
L52: }
L53: 
L54: // --- the audit: verify_overflow.mjs's own function -----------------------------
L55: let AUDIT_SRC;
L56: try {
L57:   const src = readFileSync(join(HERE, 'verify_overflow.mjs'), 'utf8');
L58:   const a = src.indexOf('const AUDIT = ');
L59:   const b = src.indexOf('\nconst browser', a);
L60:   if (a < 0 || b < 0) throw new Error('AUDIT not found');
L61:   AUDIT_SRC = src.slice(a + 'const AUDIT = '.length, b).trim().replace(/;$/, '');
L62: } catch (e) {
L63:   fail(`cannot load the overflow audit from verify_overflow.mjs (${e.message})`);
L64: }
L65: 
L66: // --- where do the shots go ------------------------------------------------------
L67: let root;
L68: try { root = execFileSync('git', ['rev-parse', '--show-toplevel'], { stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim(); }
L69: catch { root = process.cwd(); }
L70: const outDir = resolve(opt('out', join(root, '.design', 'shots')));
L71: mkdirSync(outDir, { recursive: true });
L72: 
L73: const isUrl = /^[a-z][a-z0-9+.-]*:\/\//i.test(target);
L74: let url = target;
L75: if (!isUrl) {
L76:   const abs = resolve(target);
L77:   if (!existsSync(abs)) fail(`file not found: ${abs}`);
L78:   url = pathToFileURL(abs).href;
L79: }
L80: const slug = (isUrl ? new URL(url).host + new URL(url).pathname : basename(target).replace(/\.[^.]+$/, ''))

